export type DaisyUiParityScope =
  | 'actions'
  | 'data-display'
  | 'navigation'
  | 'feedback'
  | 'data-input'
  | 'layout'
  | 'mockup';

export type DaisyUiParityStatus =
  | 'semantic-pass'
  | 'component-pass'
  | 'partially-covered'
  | 'intentional-divergence'
  | 'not-native'
  | 'gap';

export interface DaisyUiParityItem {
  scope: DaisyUiParityScope;
  id: string;
  daisyUiName: string;
  upstreamPath: string;
  status: DaisyUiParityStatus;
  nativePrimitive: string;
  notes: string;
  nextAction?: string;
  localEvidence?: string[];
}

