export const DAISYUI_PARITY_TOTALS = {
  components: 65,
} as const;

export function getDaisyUiParityComponents(status: DaisyUiParityStatus): DaisyUiParityItem[] {
  return DAISYUI_PARITY_COMPONENTS.filter((component) => component.status === status);
}
